import {legendaryMedia} from './legendary-media.mjs';
import {LegendaryVideo} from './legendary-video.mjs';
import {FILMS,shotAt} from './legendary-direction.mjs';
import {LEGENDARY_STORIES,completeStory} from './legendary-stories.mjs';
import {drawLegendaryFrame} from './legendary-art.mjs';
import {preload,ensureSprite,loadImage} from './art.mjs';
export class LegendaryCinema{
 constructor(g){this.g=g;this.videoPlayer=new LegendaryVideo(g);this.active=false;this.elapsed=0}
 play(result,{replay=false}={}){const media=legendaryMedia(result.key,{reducedMotion:this.g.state.settings.reducedMotion});if(media)return this.playMovie(result,media,{replay});const story=LEGENDARY_STORIES[parseInt(result.key)];if(!story||!this.g.dex[story.id])return Promise.resolve();if(this.active)this.finish();this.active=true;this.story=story;this.key=result.key;this.elapsed=0;this.replay=replay;this.lastAct=-1;this.film=FILMS[story.id];this.paused=false;this.previousMusic=this.g.audio.music.scene;cancelAnimationFrame(this.g.uiRaf);const keys=[result.key,...(story.id===384?['382','383']:[])];preload(keys);for(const key of keys)ensureSprite(key).then(()=>{const set=window.PMD_DATA?.[parseInt(key)]||window.PMD_REMOTE?.[parseInt(key)];if(!key.endsWith('s')&&set)for(const kind of ['Idle','Attack'])if(set[kind])loadImage(set[kind].url||`assets/pmd/${parseInt(key)}/${kind}.png`).decode().catch(()=>{})}).catch(()=>{});this.g.audio.music.setScene(story.music);const g=this.g;g.openModal(`<section class="legendary-cinema" aria-label="Cinématique de ${g.escape(g.poke(result.key).name)}"><canvas width="480" height="270" aria-label="${g.escape(story.title)}"></canvas><header><div><span>${replay?'SOUVENIR LÉGENDAIRE':'PREMIÈRE RENCONTRE'}</span><strong>${g.escape(story.location)}</strong></div><div><button data-act="legendary-pause" aria-label="Mettre la cinématique en pause">Ⅱ</button><button data-act="legendary-skip">${replay?'Fermer':'Passer la cinématique'} →</button></div></header><div class="legendary-caption"><span>${g.escape(story.title)}</span><h2></h2><p></p></div><div class="legendary-progress"><i></i></div></section>`,{locked:true,className:'legendary-dialog'});this.canvas=g.modal.querySelector('canvas');this.ctx=this.canvas.getContext('2d');this.abort=new AbortController();document.addEventListener('keydown',e=>{if(e.code==='Escape'){e.preventDefault();this.finish()}},{signal:this.abort.signal});this.duration=g.state.settings.reducedMotion?6:story.duration;this.last=performance.now();return new Promise(resolve=>{this.resolve=resolve;const frame=now=>{if(!this.active)return;const dt=Math.max(0,Math.min(.05,(now-this.last)/1000));this.last=now;if(!document.hidden&&!this.paused)this.elapsed+=dt;const t=this.elapsed/this.duration*story.duration,act=drawLegendaryFrame(this.ctx,story,this.key,t,g.state.settings.reducedMotion);if(act!==this.lastAct){this.lastAct=act;const caption=g.modal.querySelector('.legendary-caption');const labels=[story.location,story.title,story.omen,story.arrival,g.poke(result.key).name,'Une nouvelle légende rejoint ton histoire'];caption.querySelector('h2').textContent=act===4?g.poke(result.key).name:act===0?story.location:act===1?story.title:act===2?'Quelque chose s’éveille…':act===3?'L’apparition':g.poke(result.key).name;caption.querySelector('p').textContent=labels[act]||'';g.modal.querySelector('.legendary-cinema').dataset.shot=act;}g.modal.querySelector('.legendary-progress i').style.width=Math.min(100,this.elapsed/this.duration*100)+'%';if(this.elapsed>=this.duration){this.finish();return}this.frame=requestAnimationFrame(frame)};this.frame=requestAnimationFrame(frame)})}
 async playMovie(result,media,{replay=false}={}){const story=LEGENDARY_STORIES[parseInt(result.key)];if(!story||!this.g.dex[story.id])return;if(this.active)this.finish();this.active=true;this.story=story;this.key=result.key;this.elapsed=0;this.replay=replay;this.paused=false;this.previousMusic=this.g.audio.music.scene;cancelAnimationFrame(this.g.uiRaf);const outcome=await this.videoPlayer.play(media,{key:result.key,title:story.title,replay,onTime:(time,duration)=>{this.elapsed=time;this.duration=duration}});this.active=false;if(outcome.completed)completeStory(this.g.state,story.id);this.g.save();this.g.audio.music.setScene(this.previousMusic||this.g.page);if(!this.g.mode)this.g.startUIAnimation();return outcome}
 pause(){if(this.videoPlayer.active){this.videoPlayer.pause();this.paused=this.videoPlayer.userPaused;return}if(!this.active)return;this.paused=!this.paused;const b=this.g.modal.querySelector('[data-act="legendary-pause"]');if(b){b.textContent=this.paused?'▶':'Ⅱ';b.setAttribute('aria-label',this.paused?'Reprendre la cinématique':'Mettre la cinématique en pause')}this.g.audio.music.hold('cinematic',this.paused)}
 finish(){if(this.videoPlayer.active){this.videoPlayer.finish('skipped');return}if(!this.active)return;this.active=false;cancelAnimationFrame(this.frame);this.abort?.abort();completeStory(this.g.state,this.story.id);this.g.save();this.g.audio.music.hold('cinematic',false);this.g.audio.music.setScene(this.previousMusic||this.g.page);if(!this.g.mode)this.g.startUIAnimation();const resolve=this.resolve;this.resolve=null;resolve?.()}
}
